def read_rgba(path):
 b=Path(path).read_bytes(); pos=8; ds=[]
 while pos<len(b):
  n=struct.unpack(">I",b[pos:pos+4])[0]; t=b[pos+4:pos+8]; d=b[pos+8:pos+8+n]; pos+=n+12
  if t==b"IHDR":
   w,h,dep,typ,_,_,inter=struct.unpack(">IIBBBBB",d)
   assert dep==8 and typ==6 and inter==0,(dep,typ,inter)
  if t==b"IDAT": ds.append(d)
 raw=zlib.decompress(b"".join(ds)); stride=w*4; result=bytearray(w*h*4); prev=bytearray(stride); off=0
 for y in range(h):
  f=raw[off]; off+=1; row=bytearray(raw[off:off+stride]); off+=stride
  if f:
   for i in range(stride):
    a=row[i-4] if i>=4 else 0; bb=prev[i]; c=prev[i-4] if i>=4 else 0
    if f==1: v=a
    elif f==2: v=bb
    elif f==3: v=(a+bb)//2
    else:
     p=a+bb-c; pa=abs(p-a); pb=abs(p-bb); pc=abs(p-c)
     v=a if pa<=pb and pa<=pc else bb if pb<=pc else c
    row[i]=(row[i]+v)&255
  result[y*stride:(y+1)*stride]=row; prev=row
 return w,h,result
def chunk(t,d):
 return struct.pack(">I",len(d))+t+d+struct.pack(">I",zlib.crc32(t+d)&0xffffffff)
def png(w,h,pixels):
 raw=b"".join(b"\0"+pixels[y*w*4:(y+1)*w*4] for y in range(h))
 return b"\x89PNG\r\n\x1a\n"+chunk(b"IHDR",struct.pack(">IIBBBBB",w,h,8,6,0,0,0))+chunk(b"IDAT",zlib.compress(raw))+chunk(b"IEND",b"")
